```java
public int findMaxConsecutive(int[] arr) {
    // Guard against null or empty input
    if (arr == null || arr.length == 0) {
        return 0;
    }

    // maxCount  = longest streak found so far
    // currentCount = length of the current consecutive run
    int maxCount = 1;
    int currentCount = 1;

    // Stop one element early so that arr[i + 1] is always valid
    for (int i = 0; i < arr.length - 1; i++) {
        if (arr[i] == arr[i + 1]) {
            // Same as previous -> extend the current run
            currentCount++;
        } else {
            // Different -> reset the current run to 1
            currentCount = 1;
        }

        // Update the maximum whenever current run is longer
        if (currentCount > maxCount) {
            maxCount = currentCount;
        }
    }

    return maxCount;
}
